1. //! xcvrd-rs daemon — M1 bootstrap (presence + identity).
2. //!
3. //! This is deliberately a *minimal* daemon: it gets the black-box suite past the
4. //! clean-baseline fixture (which flushes `TRANSCEIVER_*`, restarts xcvrd, and
5. //! requires `TRANSCEIVER_INFO` to repopulate) so the real M1 tests execute and
6. //! pass instead of erroring at setup. The translation agents extend this into the
7. //! full daemon (DOM, CMIS state machine, errors, …) milestone by milestone.
8. //!
9. //! What it does, mirroring the Python `SfpStateUpdateTask` core:
10. //!   1. Build the logical→physical port map from CONFIG_DB (`PORT|Ethernet{n}`
11. //!      whose `index` is the emulator SFP index; here `Ethernet{i*4}` ↔ `i`).
12. //!   2. For every configured port, read identity via the HAL and publish
13. //!      `TRANSCEIVER_INFO` (every `get_transceiver_info()` field, like the Python
14. //!      CMIS branch of `post_port_sfp_info_to_db`, plus `is_replaceable`), and set
15. //!      `TRANSCEIVER_STATUS_SW` `status`/`cmis_state`.
16. //!   3. React to plug/unplug via `get_change_event`: repopulate on insert, delete
17. //!      `TRANSCEIVER_INFO` + set `status=0` on removal.
18. //!
19. //! Values are written trimmed of trailing NULs (CMIS strings are fixed-width,
20. //! NUL-padded); the observable result matches the reference xcvrd, whose outputs
21. //! the suite reads with NULs stripped.
22. 
23. use std::collections::BTreeMap;
24. use std::error::Error;
25. use std::time::Duration;
26. 
27. use platform_bridge::Platform;
28. use swss_common::{CxxString, DbConnector};
29. 
30. use crate::env;
31. 
32. const INFO_TABLE: &str = "TRANSCEIVER_INFO";
33. const STATUS_SW_TABLE: &str = "TRANSCEIVER_STATUS_SW";
34. 
35. /// Entry point: run the daemon forever. On any setup/serve error we log and retry
36. /// rather than exit, so the pmon supervisor keeps the daemon RUNNING (and the M0
37. /// deploy-smoke stays green) even if the emulator or Redis is briefly unavailable.
38. pub fn run() -> ! {
39.     eprintln!("xcvrd-rs: starting (M1 bootstrap: presence + identity)");
40.     loop {
41.         if let Err(e) = serve() {
42.             eprintln!("xcvrd-rs: serve error: {e}; retrying in 3s");
43.             std::thread::sleep(Duration::from_secs(3));
44.         }
45.     }
46. }
47. 
48. fn serve() -> Result<(), Box<dyn Error>> {
49.     let platform = env::open_platform()?; // PyO3 -> sonic_platform -> xcvr-emu
50.     let state = env::open_state_db()?; // swss-common -> STATE_DB
51.     let config = env::open_config_db()?; // swss-common -> CONFIG_DB
52. 
53.     let ports = discover_ports(&platform, &config)?;
54.     eprintln!("xcvrd-rs: {} configured ports discovered", ports.len());
55. 
56.     // Initial full sync so a freshly-flushed STATE_DB repopulates. Per-port errors
57.     // are logged but don't tear down the daemon.
58.     for (&phys, port) in &ports {
59.         if let Err(e) = sync_port(&platform, &state, phys, port) {
60.             eprintln!("xcvrd-rs: initial sync {port} (sfp {phys}) failed: {e}");
61.         }
62.     }
63.     eprintln!("xcvrd-rs: initial sync complete; watching for change events");
64. 
65.     // React to plug/unplug transitions. get_change_event blocks up to the timeout
66.     // and returns the set of physical ports whose presence changed.
67.     loop {
68.         let ev = platform.get_change_event(1000)?;
69.         for phys_str in ev.sfp.keys() {
70.             let Ok(phys) = phys_str.parse::<usize>() else { continue };
71.             if let Some(port) = ports.get(&phys) {
72.                 if let Err(e) = sync_port(&platform, &state, phys, port) {
73.                     eprintln!("xcvrd-rs: change sync {port} (sfp {phys}) failed: {e}");
74.                 }
75.             }
76.         }
77.     }
78. }
79. 
80. /// Map each configured logical port to its physical SFP index. A port is
81. /// "configured" iff CONFIG_DB has `PORT|<name>`; the emulator names SFP `i` as
82. /// `Ethernet{i*4}`, which matches the CONFIG_DB `index` field on this testbed.
83. fn discover_ports(platform: &Platform, config: &DbConnector) -> Result<BTreeMap<usize, String>, Box<dyn Error>> {
84.     let num = platform.num_sfps()?;
85.     let mut map = BTreeMap::new();
86.     for phys in 0..num {
87.         let port = format!("Ethernet{}", phys * 4);
88.         if config.exists(&format!("PORT|{port}"))? {
89.             map.insert(phys, port);
90.         }
91.     }
92.     Ok(map)
93. }
94. 
95. /// Publish (or clear) one port's identity + SW status from live HAL state.
96. fn sync_port(platform: &Platform, state: &DbConnector, phys: usize, port: &str) -> Result<(), Box<dyn Error>> {
97.     let sfp = platform.sfp(phys)?;
98.     let info_key = format!("{INFO_TABLE}|{port}");
99.     let sw_key = format!("{STATUS_SW_TABLE}|{port}");
100. 
101.     if sfp.get_presence()? {
102.         let info = sfp.get_transceiver_info()?;
103.         if let Some(obj) = info.as_object() {
104.             for (field, value) in obj {
105.                 if let Some(s) = stringify(value) {
106.                     state.hset(&info_key, field, &CxxString::from(s.as_str()))?;
107.                 }
108.             }
109.         }
110.         let replaceable = sfp.is_replaceable().unwrap_or(false);
111.         state.hset(&info_key, "is_replaceable", &CxxString::from(pybool(replaceable)))?;
112.         state.hset(&sw_key, "status", &CxxString::from("1"))?;
113.         state.hset(&sw_key, "cmis_state", &CxxString::from("READY"))?;
114.     } else {
115.         state.del(&info_key)?;
116.         state.hset(&sw_key, "status", &CxxString::from("0"))?;
117.     }
118.     Ok(())
119. }
120. 
121. /// Python-style bool rendering, matching `str(bool)` the reference daemon writes.
122. fn pybool(b: bool) -> &'static str {
123.     if b {
124.         "True"
125.     } else {
126.         "False"
127.     }
128. }
129. 
130. /// Render a `get_transceiver_info()` JSON value as the STATE_DB field string the
131. /// reference daemon writes via `str(value)`. Strings are trimmed of trailing NUL
132. /// padding (and trailing spaces); JSON nulls are skipped.
133. fn stringify(v: &serde_json::Value) -> Option<String> {
134.     use serde_json::Value;
135.     match v {
136.         Value::Null => None,
137.         Value::String(s) => Some(s.trim_end_matches('\0').trim_end().to_string()),
138.         Value::Bool(b) => Some(pybool(*b).to_string()),
139.         Value::Number(n) => Some(n.to_string()),
140.         other => Some(other.to_string()),
141.     }
142. }
143.

