1. //! HAL seam (analysis §3.6) — the mockable boundary in front of the thick
2. //! `platform-bridge` (PyO3 → the real `sonic_platform` plugin).
3. //!
4. //! The daemon logic and posters are written against [`Hal`]/[`SfpHandle`] (as
5. //! `&dyn`), so production wraps `platform-bridge` ([`BridgeHal`]) while unit tests
6. //! inject canned values via `crate::mock::{MockHal, MockSfp}` — the Rust analogue
7. //! of the Python tests' `@patch('..._wrapper_get_transceiver_info', MagicMock(...))`
8. //! and `MagicMock()` SFP objects.
9. //!
10. //! No CMIS/SFF decode lives here: complex results are `serde_json::Value` straight
11. //! from the bridge; scalars are typed.
12. 
13. use std::sync::Arc;
14. 
15. use pyo3::prelude::*;
16. use pyo3::types::PyDict;
17. use serde_json::Value;
18. 
19. use crate::error::{Result, XcvrdError};
20. 
21. /// One transceiver change-event poll, re-exported from the bridge so the daemon
22. /// (and the mock) share one shape: `{sfp: {phys: code}, sfp_error: {phys: code}}`.
23. pub use platform_bridge::ChangeEvent;
24. 
25. /// The transceiver plant: `chassis.get_num_sfps()/get_sfp(i)/get_change_event(t)`.
26. pub trait Hal: Send + Sync {
27.     /// `chassis.get_num_sfps()`.
28.     fn num_sfps(&self) -> Result<usize>;
29.     /// `chassis.get_sfp(index)` → a per-module handle.
30.     fn sfp(&self, index: usize) -> Result<Box<dyn SfpHandle>>;
31.     /// `chassis.get_change_event(timeout_ms)`.
32.     fn get_change_event(&self, timeout_ms: u64) -> Result<ChangeEvent>;
33. }
34. 
35. /// A single transceiver slot (`SfpOptoeBase` + emulator overrides). All the
36. /// identity/DOM/status/VDM getters xcvrd calls, plus the `call_json` escape hatch
37. /// for the no-arg methods without a typed bridge wrapper (analysis §3.5 table).
38. pub trait SfpHandle {
39.     fn get_presence(&self) -> Result<bool>;
40.     fn is_replaceable(&self) -> Result<bool>;
41.     fn get_reset_status(&self) -> Result<bool>;
42.     fn sfp_type(&self) -> Result<String>;
43.     fn get_error_description(&self) -> Result<Option<String>>;
44.     fn get_transceiver_info(&self) -> Result<Value>;
45.     fn get_transceiver_dom_real_value(&self) -> Result<Value>;
46.     fn get_transceiver_status(&self) -> Result<Value>;
47.     fn get_transceiver_threshold_info(&self) -> Result<Value>;
48.     fn get_lpmode(&self) -> Result<bool>;
49.     fn set_lpmode(&self, on: bool) -> Result<bool>;
50.     fn reset(&self) -> Result<bool>;
51.     /// Call any no-arg Python `Sfp` method, marshalling the result as JSON
52.     /// (`get_transceiver_status_flags`, `get_transceiver_dom_flags`,
53.     /// `get_temperature`, `get_transceiver_pm`, VDM getters, …).
54.     fn call_json(&self, method: &str) -> Result<Value>;
55.     /// `SfpOptoeBase.read_eeprom(offset, num_bytes)` — read raw transceiver EEPROM at
56.     /// the flat linear `offset`. Returns `Ok(None)` on a plugin read miss. Used to
57.     /// decode the module-level DOM flag group (CMIS byte 00h:9) directly from the latched
58.     /// byte — so the temperature and supply-voltage flags are always published together —
59.     /// and to read back the CMIS staged-control-set bytes during CMIS datapath bring-up.
60.     fn read_eeprom(&self, offset: usize, num_bytes: usize) -> Result<Option<Vec<u8>>>;
61.     /// `SfpOptoeBase.write_eeprom(offset, num_bytes, buf)` — write raw transceiver
62.     /// EEPROM at the flat linear `offset`. The CMIS manager drives the real page-10h
63.     /// datapath control bytes (DataPathDeinit 10h:128, OutputDisableTx 10h:130,
64.     /// DPConfigLane 10h:145-152, ApplyDPInitLane 10h:143) through this seam — the same
65.     /// register writes `CmisApi` performs; CMIS decode itself stays in Python.
66.     fn write_eeprom(&self, offset: usize, data: &[u8]) -> Result<bool>;
67. }
68. 
69. /// A daemon-owned `sonic_platform` chassis used ONLY for the DOM-threshold read.
70. ///
71. /// The thick `platform-bridge` marshals every complex getter through
72. /// `json.dumps(obj, default=str)` + `serde_json::from_str`. A DEFAULT (never-enriched)
73. /// transceiver decodes its zero-power page-02h thresholds to Python `float('-inf')`,
74. /// which `json.dumps` emits as the bare token `-Infinity` — NOT valid strict JSON, so
75. /// `serde_json` rejects it and `get_transceiver_threshold_info()` fails outright.
76. /// `TRANSCEIVER_DOM_THRESHOLD` is then never published for such a module (e.g. the
77. /// spare admin-up logical port the M7 lifecycle e2e exercises, which is never
78. /// threshold-enriched), and — because M7 recovery treats a threshold-missing port as
79. /// un-baselined — it re-posts DOM/VDM thresholds for every such port each interval,
80. /// flooding the PyO3 bridge and starving the DOM flag poll.
81. ///
82. /// The bridge is a fixed dependency, so the daemon re-reads the thresholds itself via
83. /// PyO3 and sanitizes the non-finite floats to their Python `str()` form
84. /// (`"-inf"`/`"inf"`/`"nan"`) — exactly what the reference daemon posts — before
85. /// parsing. Used for the threshold read only; every other getter and the change-event
86. /// poll stay on the bridge unchanged, so this cannot regress those paths.
87. struct ThrChassis {
88.     chassis: Py<PyAny>,
89. }
90. 
91. impl ThrChassis {
92.     fn new() -> Result<Self> {
93.         Python::with_gil(|py| {
94.             let module = py
95.                 .import_bound("sonic_platform.platform")
96.                 .map_err(|e| XcvrdError::Bridge(format!("import sonic_platform.platform: {e}")))?;
97.             let platform = module
98.                 .getattr("Platform")
99.                 .and_then(|p| p.call0())
100.                 .map_err(|e| XcvrdError::Bridge(format!("Platform(): {e}")))?;
101.             let chassis = platform
102.                 .call_method0("get_chassis")
103.                 .map_err(|e| XcvrdError::Bridge(format!("get_chassis(): {e}")))?;
104.             Ok(ThrChassis {
105.                 chassis: chassis.unbind(),
106.             })
107.         })
108.     }
109. 
110.     /// Read the `TRANSCEIVER_DOM_THRESHOLD` source dict for physical `index`,
111.     /// sanitizing non-finite floats so the result is strict JSON. `Value::Null` when
112.     /// the slot is absent/None (the poster then no-ops, exactly as for an absent
113.     /// module or an empty dict).
114.     fn read_threshold_json(&self, index: usize) -> Result<Value> {
115.         Python::with_gil(|py| {
116.             let sfp = self
117.                 .chassis
118.                 .bind(py)
119.                 .call_method1("get_sfp", (index,))
120.                 .map_err(|e| XcvrdError::Bridge(format!("get_sfp({index}): {e}")))?;
121.             if sfp.is_none() {
122.                 return Ok(Value::Null);
123.             }
124.             let raw = sfp
125.                 .call_method0("get_transceiver_threshold_info")
126.                 .map_err(|e| XcvrdError::Bridge(format!("get_transceiver_threshold_info: {e}")))?;
127.             if raw.is_none() {
128.                 return Ok(Value::Null);
129.             }
130.             // Same shape as the bridge's `py_to_json` (json.dumps default=str), but the
131.             // resulting string is sanitized before parsing so the `-Infinity`/`NaN`
132.             // tokens a default module produces don't defeat `serde_json`.
133.             let json = py
134.                 .import_bound("json")
135.                 .map_err(|e| XcvrdError::Bridge(format!("import json: {e}")))?;
136.             let str_fn = py
137.                 .import_bound("builtins")
138.                 .and_then(|b| b.getattr("str"))
139.                 .map_err(|e| XcvrdError::Bridge(format!("builtins.str: {e}")))?;
140.             let kwargs = PyDict::new_bound(py);
141.             kwargs
142.                 .set_item("default", str_fn)
143.                 .map_err(|e| XcvrdError::Bridge(format!("set default kwarg: {e}")))?;
144.             let dumped = json
145.                 .call_method("dumps", (raw,), Some(&kwargs))
146.                 .map_err(|e| XcvrdError::Bridge(format!("json.dumps: {e}")))?;
147.             let s: String = dumped
148.                 .extract()
149.                 .map_err(|e| XcvrdError::Bridge(format!("extract dumped json: {e}")))?;
150.             serde_json::from_str(&sanitize_nonfinite_json(&s))
151.                 .map_err(|e| XcvrdError::Bridge(format!("parse threshold json: {e}")))
152.         })
153.     }
154. }
155. 
156. /// Rewrite the non-finite JSON number literals Python's `json.dumps` emits
157. /// (`-Infinity`/`Infinity`/`NaN`, all invalid in strict JSON) to their Python `str()`
158. /// string form (`"-inf"`/`"inf"`/`"nan"`), leaving everything else — including any
159. /// text that happens to contain those words INSIDE a JSON string — untouched. This
160. /// lets `serde_json` parse a default transceiver's zero/`-inf` DOM thresholds, and the
161. /// resulting strings render through `value_to_py_str` to the exact field text the
162. /// Python daemon posts (`str(float('-inf')) == "-inf"`).
163. fn sanitize_nonfinite_json(s: &str) -> String {
164.     let mut out = String::with_capacity(s.len());
165.     let mut in_str = false;
166.     let mut i = 0;
167.     while i < s.len() {
168.         let rest = &s[i..];
169.         let ch = rest.chars().next().unwrap();
170.         let ch_len = ch.len_utf8();
171.         if in_str {
172.             out.push(ch);
173.             if ch == '\\' {
174.                 // Copy the escaped char verbatim so an escaped quote can't end the string.
175.                 if let Some(next) = rest[ch_len..].chars().next() {
176.                     out.push(next);
177.                     i += ch_len + next.len_utf8();
178.                     continue;
179.                 }
180.             } else if ch == '"' {
181.                 in_str = false;
182.             }
183.             i += ch_len;
184.             continue;
185.         }
186.         if ch == '"' {
187.             in_str = true;
188.             out.push('"');
189.             i += ch_len;
190.             continue;
191.         }
192.         // Order matters: `-Infinity` must be tried before `Infinity`.
193.         if rest.starts_with("-Infinity") {
194.             out.push_str("\"-inf\"");
195.             i += "-Infinity".len();
196.             continue;
197.         }
198.         if rest.starts_with("Infinity") {
199.             out.push_str("\"inf\"");
200.             i += "Infinity".len();
201.             continue;
202.         }
203.         if rest.starts_with("NaN") {
204.             out.push_str("\"nan\"");
205.             i += "NaN".len();
206.             continue;
207.         }
208.         out.push(ch);
209.         i += ch_len;
210.     }
211.     out
212. }
