340. mod tests {
341.     use super::sanitize_nonfinite_json;
342.     use crate::dom::utilities::db::value_to_py_str;
343.     use serde_json::Value;
344. 
345.     fn parse(s: &str) -> Value {
346.         serde_json::from_str(&sanitize_nonfinite_json(s))
347.             .unwrap_or_else(|e| panic!("sanitized json must parse: {e}\ninput: {s}"))
348.     }
349. 
350.     #[test]
351.     fn bare_nonfinite_tokens_become_quoted_python_str_form() {
352.         // Exactly what Python `json.dumps({'temp': float('-inf'), ...}, default=str)`
353.         // emits for a default module's zero-power thresholds.
354.         let raw = r#"{"temphighalarm": -Infinity, "vcchighalarm": Infinity, "txbiashighalarm": NaN}"#;
355.         let v = parse(raw);
356.         assert_eq!(v["temphighalarm"], Value::String("-inf".into()));
357.         assert_eq!(v["vcchighalarm"], Value::String("inf".into()));
358.         assert_eq!(v["txbiashighalarm"], Value::String("nan".into()));
359.     }
360. 
361.     #[test]
362.     fn quoted_field_text_is_untouched() {
363.         // The words must only be rewritten as bare number tokens, never inside strings.
364.         let raw = r#"{"note": "value is -Infinity or NaN", "x": -Infinity}"#;
365.         let v = parse(raw);
366.         assert_eq!(
367.             v["note"],
368.             Value::String("value is -Infinity or NaN".into())
369.         );
370.         assert_eq!(v["x"], Value::String("-inf".into()));
371.     }
372. 
373.     #[test]
374.     fn escaped_quote_inside_string_does_not_end_it_early() {
375.         let raw = r#"{"note": "a \"quoted -Infinity\" word", "x": Infinity}"#;
376.         let v = parse(raw);
377.         assert_eq!(v["note"], Value::String(r#"a "quoted -Infinity" word"#.into()));
378.         assert_eq!(v["x"], Value::String("inf".into()));
379.     }
380. 
381.     #[test]
382.     fn finite_and_ordinary_json_is_byte_identical() {
383.         // Enriched / test-written thresholds are finite and must be preserved exactly.
384.         let raw = r#"{"temphighalarm": 75.0, "temphighwarning": 70, "vendor": "ACME", "ok": true, "n": null}"#;
385.         assert_eq!(sanitize_nonfinite_json(raw), raw);
386.         let v = parse(raw);
387.         assert_eq!(v["temphighalarm"], serde_json::json!(75.0));
388.         assert_eq!(v["temphighwarning"], serde_json::json!(70));
389.         assert_eq!(v["vendor"], Value::String("ACME".into()));
390.     }
391. 
392.     #[test]
393.     fn negative_finite_numbers_are_not_confused_with_neg_infinity() {
394.         let raw = r#"{"a": -40.0, "b": -Infinity}"#;
395.         let v = parse(raw);
396.         assert_eq!(v["a"], serde_json::json!(-40.0));
397.         assert_eq!(v["b"], Value::String("-inf".into()));
398.     }
