400.     #[test]
401.     fn sanitized_nonfinite_renders_to_python_str_field_text() {
402.         // The posted STATE_DB field text must match the Python daemon's `str(value)`.
403.         let raw = r#"{"temphighalarm": -Infinity, "vcchighalarm": Infinity, "txpower": NaN}"#;
404.         let v = parse(raw);
405.         let obj = v.as_object().unwrap();
406.         assert_eq!(value_to_py_str(&obj["temphighalarm"]), "-inf");
407.         assert_eq!(value_to_py_str(&obj["vcchighalarm"]), "inf");
408.         assert_eq!(value_to_py_str(&obj["txpower"]), "nan");
409.     }
