413.         assert_eq!(sanitize_nonfinite_json(""), "");
414.         assert_eq!(sanitize_nonfinite_json("{}"), "{}");
415.         assert_eq!(sanitize_nonfinite_json(r#"{"a": 1}"#), r#"{"a": 1}"#);
