29.     fn set(&self, key: &str, fvs: &[(String, String)]);
30.     /// Merge a single field into a row (real `HSET`; used for the `cmis_state`
31.     /// projection so it never clobbers `status`/`error`).
32.     fn hset(&self, key: &str, field: &str, value: &str);
