49. /// Real table: a named view over a shared STATE_DB [`DbConnector`].
50. ///
51. /// The daemon is the sole writer of `TRANSCEIVER_*`, so rows are addressed by the
52. /// explicit composite key `"<table>|<logical_port>"` (exactly what the M1 bootstrap
53. /// and the e2e harness read, e.g. `TRANSCEIVER_INFO|Ethernet0`) - no dependency on
54. /// `Table`'s separator handling. A local `keys` index tracks what we've written so
55. /// `get_keys`/`get_size` stay meaningful without a Redis `KEYS`/`SCAN`.
56. ///
57. /// `DbConnector` is `Send` but not `Sync`, so it is held behind an `Arc<Mutex<_>>`
58. /// (which is `Send + Sync`) to satisfy `DbTable: Send + Sync`; the two transceiver
59. /// tables share one connection.
60. pub struct RealDbTable {
61.     conn: Arc<Mutex<DbConnector>>,
62.     table_name: String,
63.     /// Redis key separator between the table name and the row key. STATE_DB /
64.     /// CONFIG_DB use `"|"` (the default); APPL_DB tables (e.g. `PORT_TABLE`) use
65.     /// `":"`. See [`RealDbTable::new_with_sep`].
66.     sep: String,
67.     keys: Mutex<BTreeSet<String>>,
68. }
69. 
70. impl RealDbTable {
71.     pub fn new(conn: Arc<Mutex<DbConnector>>, table_name: impl Into<String>) -> Self {
72.         Self::new_with_sep(conn, table_name, "|")
73.     }
74. 
75.     /// Build a table view whose Redis key is `"<table><sep><key>"`. Use `":"` for
76.     /// APPL_DB tables such as `PORT_TABLE` (`PORT_TABLE:Ethernet0`); STATE_DB and
77.     /// CONFIG_DB use the `"|"` default via [`RealDbTable::new`].
78.     pub fn new_with_sep(
79.         conn: Arc<Mutex<DbConnector>>,
80.         table_name: impl Into<String>,
81.         sep: impl Into<String>,
82.     ) -> Self {
83.         RealDbTable {
84.             conn,
85.             table_name: table_name.into(),
86.             sep: sep.into(),
87.             keys: Mutex::new(BTreeSet::new()),
88.         }
89.     }
90. 
91.     fn redis_key(&self, key: &str) -> String {
92.         format!("{}{}{}", self.table_name, self.sep, key)
93.     }
94. 
95.     fn track(&self, key: &str) {
96.         self.locked_keys().insert(key.to_string());
97.     }
98. 
99.     fn untrack(&self, key: &str) {
100.         self.locked_keys().remove(key);
101.     }
102. 
103.     /// Lock the shared STATE_DB connection, recovering from a poisoned mutex.
104.     ///
105.     /// The `DbConnector` is shared (`Arc<Mutex<_>>`) across the DOM/CMIS/SFP threads.
106.     /// If one thread panics while holding the lock (e.g. a PyO3 bridge error, or an
107.     /// `eprintln!` hitting a broken supervisor stderr pipe mid-write), a plain
108.     /// `.lock().unwrap()` on the other threads would panic too, cascading a single
109.     /// transient fault into a full `serve` teardown + chassis rebuild — which resets
110.     /// the emulator change-event baseline and drops in-flight SFP-error transitions.
111.     /// Python's GIL means one thread's exception never corrupts a shared object, so we
112.     /// mirror that: recover the guard and carry on. The connection is only read/written
113.     /// under this lock, so no partially-mutated invariant is exposed.
114.     fn locked_conn(&self) -> MutexGuard<'_, DbConnector> {
115.         self.conn.lock().unwrap_or_else(|e| e.into_inner())
116.     }
117. 
118.     /// Lock the per-table key set, recovering from a poisoned mutex (see
119.     /// [`Self::locked_conn`]).
120.     fn locked_keys(&self) -> MutexGuard<'_, BTreeSet<String>> {
121.         self.keys.lock().unwrap_or_else(|e| e.into_inner())
122.     }
123. }
